<template>
  <div class="container-fluid my-4">
    <!-- Header -->
    <div class="d-flex justify-content-between align-items-center mb-3">
      <div>
        <p class="text-uppercase text-primary small mb-1">Content Management</p>
        <h1 class="h3 mb-0">Pages</h1>
      </div>
      <button class="btn btn-primary" @click="openCreate">+ New Page</button>
    </div>
    <!-- Alert -->
    <div v-if="alert.show" :class="['alert', alert.type === 'error' ? 'alert-danger' : 'alert-success']">
      {{ alert.message }}
    </div>

    <!-- Table -->
    <div v-if="loading" class="text-center py-5">Loading…</div>
    <div v-else-if="!filteredPages.length" class="text-center py-5">No pages found.</div>
    <div v-else class="table-responsive">
      <table class="table table-hover align-middle">
        <thead class="table-light text-uppercase small">
          <tr>
            <th></th><th>#</th><th>Title</th><th>Slug</th><th>Status</th>
            <th>Sections</th><th>Media</th><th>Created</th><th>Actions</th>
          </tr>
        </thead>
        <tbody v-for="p in filteredPages" :key="p.id">
          <tr>
            <td>
              <button class="btn btn-sm btn-outline-secondary" @click="toggleExpand(p.id)">
                {{ expandedId === p.id ? '−' : '+' }}
              </button>
            </td>
            <td>{{ p.id }}</td>
            <td>{{ p.title }}</td>
            <td><code>{{ p.slug }}</code></td>
            <td>
              <span :class="['badge', p.status === 'published' ? 'bg-success' : p.status === 'draft' ? 'bg-warning text-dark' : 'bg-secondary']">
                {{ p.status }}
              </span>
            </td>
            <td>{{ p.sections?.length ?? 0 }}</td>
            <td>{{ p.media?.length ?? 0 }}</td>
            <td>{{ formatDate(p.created_at) }}</td>
            <td>
              <button class="btn btn-sm btn-outline-primary me-1" @click="openEdit(p)"><i class="bi bi-pencil fs-6"></i></button>
              <button class="btn btn-sm btn-outline-danger me-1" @click="confirmDelete(p)"><i class="bi bi-trash-fill fs-6"></i></button>
<button class="btn btn-outline-dark me-1" @click="openPreview(p.id)">
  <i class="bi bi-eye"></i>
</button>
              <router-link :to="`/page/${p.id}`" class="btn btn-sm btn-outline-secondary"><i class="bi bi-arrow-right fs-6"></i></router-link>
            </td>
          </tr>

          <!-- Expand preview -->
          <tr v-if="expandedId === p.id">
            <td colspan="9">
              <div class="row g-3 p-2">
                <div class="col-md-3">
                  <h6 class="text-uppercase small text-muted mb-2">Sections</h6>
                  <ul class="list-group list-group-flush">
                    <li v-for="s in p.sections" :key="s.id" class="list-group-item d-flex justify-content-between align-items-center px-0">
                      <span class="badge bg-primary">{{ s.type }}</span>
                      <span v-if="s.children?.length" class="badge bg-light text-dark border">{{ s.children.length }} children</span>
                    </li>
                    <li v-if="!p.sections?.length" class="list-group-item px-0 text-muted small">None</li>
                  </ul>
                </div>
                <div class="col-md-9">
                  <h6 class="text-uppercase small text-muted mb-2">Media</h6>
                  <ul class="list-group list-group-flush">
                    <li v-for="m in p.media" :key="m.id" class="list-group-item p-0">
                      <a :href="mediaUrl(m.file_path)" target="_blank" class="d-flex align-items-center gap-2 p-2 text-decoration-none text-dark">
                        <img v-if="m.type === 'image'" :src="mediaUrl(m.file_path)" class="img-thumbnail" style="width:36px;height:36px;object-fit:cover;" />
                        <span v-else>📄</span>
                        <span class="text-truncate">{{ m.file_path.split('/').pop() }}</span>
                        <span class="badge bg-secondary ms-auto">{{ m.type }}</span>
                      </a>
                    </li>
                    <li v-if="!p.media?.length" class="list-group-item px-0 text-muted small">None</li>
                  </ul>
                </div>
              </div>
            </td>
          </tr>
        </tbody>
      </table>
    </div>

    <!-- ── Create / Edit Modal ── -->
    <div v-if="modal.show" class="modal fade show d-block" tabindex="-1">
      <div class="modal-dialog modal-fullscreen modal-dialog-scrollable">
        <div class="modal-content">
          <div class="modal-header">
            <h5 class="modal-title">{{ modal.mode === 'create' ? 'New Page' : 'Edit: ' + form.title }}</h5>
            <button type="button" class="btn-close" @click="closeModal"></button>
          </div>

          <div class="modal-body">
            <div class="row g-4">

              <!-- Left: Page Details -->
              <div class="col-md-3">
                <h6 class="text-uppercase small text-muted mb-3">Page Details</h6>
                <div class="mb-3">
                  <label class="form-label">Title</label>
                  <input v-model="form.title" class="form-control" @input="autoSlug" placeholder="Page title" />
                  <div v-if="errors.title" class="text-danger small mt-1">{{ errors.title }}</div>
                </div>
                <div class="mb-3">
                  <label class="form-label">Slug</label>
                  <input v-model="form.slug" class="form-control" placeholder="page-slug" />
                  <div v-if="errors.slug" class="text-danger small mt-1">{{ errors.slug }}</div>
                </div>
                <div class="mb-3">
                  <label class="form-label">Status</label>
                  <select v-model="form.status" class="form-select">
                    <option value="published">Published</option>
                    <option value="draft">Draft</option>
                    <option value="archived">Archived</option>
                  </select>
                </div>
              </div>

              <!-- Middle: Sections -->
              <div class="col-md-5">
                <div class="d-flex justify-content-between align-items-center mb-3">
                  <h6 class="text-uppercase small text-muted mb-0">Sections ({{ form.sections.length }})</h6>
                  <button class="btn btn-sm btn-outline-primary" @click="addSection">+ Add Section</button>
                </div>

                <div v-if="!form.sections.length" class="text-muted small py-2">No sections yet. Click + Add Section.</div>

                <div v-for="(s, si) in form.sections" :key="si" class="card mb-3 border-primary border-opacity-25">
                  <div class="card-header d-flex justify-content-between align-items-center py-2 px-3 bg-light">
                    <strong class="small">{{ s.type || 'Section ' + (si + 1) }}</strong>
                    <div class="d-flex gap-2 align-items-center">
                      <label class="small text-muted mb-0">Position</label>
                      <input v-model.number="s.position" type="number" class="form-control form-control-sm" style="width:60px;" min="0" />
                      <button class="btn btn-xs btn-outline-danger" @click="removeSection(si)">✕</button>
                    </div>
                  </div>
                  <div class="card-body p-3">

                    <!-- Section type -->
                    <div class="mb-3">
                      <label class="form-label small fw-semibold">Section Type</label>
                      <input v-model="s.type" class="form-control form-control-sm" placeholder="e.g. hero, banner, text-block" />
                      <div class="form-text">A label to identify what this section is.</div>
                    </div>

                    <!-- Content fields -->
                    <div class="mb-3">
                      <div class="d-flex justify-content-between align-items-center mb-2">
                        <label class="form-label small fw-semibold mb-0">Content Fields</label>
                        <button class="btn btn-xs btn-outline-secondary" @click="addContentField(si)">+ Field</button>
                      </div>
                      <div class="form-text mb-2">Add the data this section will display (e.g. title, body, image URL).</div>
                      <div v-if="!s.contentFields.length" class="text-muted small">No fields yet.</div>
                      <div v-for="(f, fi) in s.contentFields" :key="fi" class="input-group input-group-sm mb-1">
                        <input v-model="f.key" class="form-control" placeholder="Field name (e.g. title)" />
                        <input v-model="f.value" class="form-control" placeholder="Value (e.g. Welcome!)" />
                        <button class="btn btn-outline-danger" @click="removeContentField(si, fi)">✕</button>
                      </div>
                    </div>

                    <!-- Attributes (CSS classes, styles) -->
                    <div class="mb-3">
                      <div class="d-flex justify-content-between align-items-center mb-2">
                        <label class="form-label small fw-semibold mb-0">Styling / Attributes</label>
                        <button class="btn btn-xs btn-outline-secondary" @click="addAttrField(si)">+ Attribute</button>
                      </div>
                      <div class="form-text mb-2">Control how this section looks (e.g. class → container bg-dark text-white).</div>
                      <div v-if="!s.attrFields.length" class="text-muted small">No attributes yet.</div>
                      <div v-for="(a, ai) in s.attrFields" :key="ai" class="input-group input-group-sm mb-1">
                        <select v-model="a.key" class="form-select form-select-sm" style="max-width:120px;">
                          <option value="class">class</option>
                          <option value="style">style</option>
                          <option value="id">id</option>
                        </select>
                        <input v-model="a.value" class="form-control" :placeholder="a.key === 'class' ? 'e.g. container bg-primary text-white' : a.key === 'style' ? 'e.g. color:red; padding:1rem' : 'e.g. hero-section'" />
                        <button class="btn btn-outline-danger" @click="removeAttrField(si, ai)">✕</button>
                      </div>
                    </div>

                    <!-- Children -->
                    <div class="border-top pt-3">
                      <div class="d-flex justify-content-between align-items-center mb-2">
                        <label class="form-label small fw-semibold mb-0">Child Sections ({{ s.children.length }})</label>
                        <button class="btn btn-xs btn-outline-secondary" @click="addChild(si)">+ Child</button>
                      </div>
                      <div class="form-text mb-2">Child sections are nested inside this section.</div>

                      <div v-for="(c, ci) in s.children" :key="ci" class="card mb-2 border-secondary border-opacity-25">
                        <div class="card-header d-flex justify-content-between align-items-center py-1 px-2 bg-light">
                          <small class="fw-semibold">{{ c.type || 'Child ' + (ci + 1) }}</small>
                          <div class="d-flex gap-2 align-items-center">
                            <input v-model.number="c.position" type="number" class="form-control form-control-sm" style="width:55px;" placeholder="Pos" min="0" />
                            <button class="btn btn-xs btn-outline-danger" @click="removeChild(si, ci)">✕</button>
                          </div>
                        </div>
                        <div class="card-body p-2">
                          <div class="mb-2">
                            <input v-model="c.type" class="form-control form-control-sm" placeholder="Child type (e.g. text, image)" />
                          </div>
                          <!-- Child content fields -->
                          <div class="mb-2">
                            <div class="d-flex justify-content-between align-items-center mb-1">
                              <small class="text-muted">Content Fields</small>
                              <button class="btn btn-xs btn-outline-secondary" @click="addChildContentField(si, ci)">+ Field</button>
                            </div>
                            <div v-for="(f, fi) in c.contentFields" :key="fi" class="input-group input-group-sm mb-1">
                              <input v-model="f.key" class="form-control" placeholder="Field name" />
                              <input v-model="f.value" class="form-control" placeholder="Value" />
                              <button class="btn btn-outline-danger" @click="removeChildContentField(si, ci, fi)">✕</button>
                            </div>
                          </div>
                          <!-- child attributes -->
                           <div class="mb-2">
  <div class="d-flex justify-content-between align-items-center mb-1">
    <small class="text-muted">Attributes</small>
    <button class="btn btn-xs btn-outline-secondary" @click="addChildAttrField(si, ci)">+ Attribute</button>
  </div>

  <div v-if="!c.attrFields.length" class="text-muted small">No attributes yet.</div>

  <div v-for="(a, ai) in c.attrFields" :key="ai" class="input-group input-group-sm mb-1">
    <select v-model="a.key" class="form-select form-select-sm" style="max-width:120px;">
      <option value="class">class</option>
      <option value="style">style</option>
      <option value="id">id</option>
    </select>
    <input v-model="a.value" class="form-control" />
    <button class="btn btn-outline-danger" @click="removeChildAttrField(si, ci, ai)">✕</button>
  </div>
</div>
                        </div>
                      </div>
                    </div>

                  </div>
                </div>
              </div>

              <!-- Right: Media -->
              <div class="col-md-4">
                <div class="d-flex justify-content-between align-items-center mb-3">
                  <h6 class="text-uppercase small text-muted mb-0">Media ({{ form.media.length }})</h6>
                  <button class="btn btn-sm btn-outline-primary" @click="addMedia">+ Add Media</button>
                </div>

                <div v-if="!form.media.length" class="text-muted small py-2">No media yet. Click + Add Media.</div>

                <div v-for="(m, mi) in form.media" :key="mi" class="card mb-2">
                  <div class="card-header d-flex justify-content-between align-items-center py-2 px-3 bg-light">
                    <span class="badge bg-secondary">{{ m.type }}</span>
                    <button class="btn btn-xs btn-outline-danger" @click="removeMedia(mi)">✕ Remove</button>
                  </div>
                  <div class="card-body p-3">
                    <div class="mb-2">
                      <label class="form-label small fw-semibold">Media Type</label>
                      <select v-model="m.type" class="form-select form-select-sm">
                        <option value="image">Image</option>
                        <option value="document">Document</option>
                        <option value="video">Video</option>
                        <option value="audio">Audio</option>
                      </select>
                    </div>
                    <div class="mb-2">
                      <label class="form-label small fw-semibold">File Path / URL</label>
                      <input v-model="m.file_path" class="form-control form-control-sm" placeholder="uploads/images/photo.jpg or https://…" />
                    </div>
                    <div v-if="m.file_path && m.type === 'image'">
                      <img :src="mediaUrl(m.file_path)" class="img-thumbnail w-100" style="max-height:100px;object-fit:cover;"
                        @error="e => e.target.style.display='none'" @load="e => e.target.style.display='block'" />
                    </div>
                  </div>
                </div>
              </div>

            </div>
          </div>

          <div class="modal-footer">
            <button class="btn btn-secondary" @click="closeModal">Cancel</button>
            <button class="btn btn-primary" :disabled="saving" @click="submitForm">
              <span v-if="saving" class="spinner-border spinner-border-sm me-1"></span>
              {{ modal.mode === 'create' ? 'Create Page' : 'Save Changes' }}
            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- Delete Modal -->
    <div v-if="deleteTarget" class="modal fade show d-block" tabindex="-1">
      <div class="modal-dialog modal-sm">
        <div class="modal-content">
          <div class="modal-header">
            <h5 class="modal-title">Delete Page</h5>
            <button class="btn-close" @click="deleteTarget = null"></button>
          </div>
          <div class="modal-body">Delete <strong>{{ deleteTarget.title }}</strong>? This cannot be undone.</div>
          <div class="modal-footer">
            <button class="btn btn-secondary btn-sm" @click="deleteTarget = null">Cancel</button>
            <button class="btn btn-danger btn-sm" :disabled="saving" @click="deletePage">
              <span v-if="saving" class="spinner-border spinner-border-sm me-1"></span>
              Delete
            </button>
          </div>
        </div>
      </div>
    </div>

    <div v-if="modal.show || deleteTarget" class="modal-backdrop fade show" @click="modal.show ? closeModal() : deleteTarget = null"></div>
  </div>

<!-- Preview Modal -->
<div v-if="previewPage !== null" class="modal fade show d-block" tabindex="-1">
  <div class="modal-dialog modal-fullscreen modal-dialog-scrollable">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title">
          {{ previewPage.loading ? 'Loading…' : previewPage.title }}
        </h5>
        <button class="btn-close" @click="previewPage = null"></button>
      </div>

      <div class="modal-body">
        <div v-if="previewPage.loading" class="text-center py-5">
          <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
          </div>
        </div>

        <div v-else>
          <SectionNode
            v-for="section in previewPage.sections"
            :key="section.id"
            :node="section"
          />

          <div v-if="previewPage.media?.length" class="media-section mt-3">
            <h6>Media</h6>
            <div class="d-flex flex-wrap gap-2">
              <template v-for="m in previewPage.media" :key="m.id">
                <img v-if="m.type==='image'" :src="mediaUrl(m.file_path)" class="img-thumbnail" style="max-width:120px;" />
                <a v-else :href="mediaUrl(m.file_path)" target="_blank" class="btn btn-outline-secondary btn-sm">
                  📄 {{ m.file_path.split('/').pop() }}
                </a>
              </template>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>

</template>

<script setup>
import { ref, computed, onMounted } from 'vue'
import axios from 'axios'
const preview = ref(false)
const APP_URL = 'https://bushman.ink'
const api = axios.create({ baseURL: `${APP_URL}/api/v2/` })
import { defineComponent, h } from 'vue'



const pages        = ref([])
const loading      = ref(true)
const saving       = ref(false)
const search       = ref('')
const expandedId   = ref(null)
const deleteTarget = ref(null)
const modal        = ref({ show: false, mode: 'create' })
const errors       = ref({})
const alert        = ref({ show: false, type: 'success', message: '' })
let alertTimer     = null

// ── Form ──────────────────────────────────────────────────────────────────────
const blankForm = () => ({ id: null, title: '', slug: '', status: 'published', sections: [], media: [] })
const form = ref(blankForm())

// ── Helpers ───────────────────────────────────────────────────────────────────
const filteredPages = computed(() => {
  const q = search.value.toLowerCase()
  return pages.value.filter(p => p.title.toLowerCase().includes(q) || p.slug.toLowerCase().includes(q))
})

const formatDate = (iso) => new Date(iso).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })

const mediaUrl = (path) => {
  if (!path) return ''
  return /^https?:\/\//i.test(path) ? path : `${APP_URL}/${path}`
}

const autoSlug = () => {
  if (modal.value.mode === 'create')
    form.value.slug = form.value.title.toLowerCase().trim().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-')
}

const showAlert = (message, type = 'success') => {
  clearTimeout(alertTimer)
  alert.value = { show: true, type, message }
  alertTimer = setTimeout(() => (alert.value.show = false), 3500)
}

const validate = () => {
  const e = {}
  if (!form.value.title.trim()) e.title = 'Title is required.'
  if (!form.value.slug.trim())  e.slug  = 'Slug is required.'
  errors.value = e
  return !Object.keys(e).length
}

const toggleExpand = (id) => { expandedId.value = expandedId.value === id ? null : id }

// ── Convert object → key/value pair array ─────────────────────────────────────
const objToFields  = (obj) => Object.entries(obj ?? {}).map(([key, value]) => ({ key, value }))
const fieldsToObj  = (fields) => Object.fromEntries(fields.filter(f => f.key.trim()).map(f => [f.key.trim(), f.value]))

// ── Section blanks ────────────────────────────────────────────────────────────
const blankSection = () => ({ id: undefined, type: '', position: 0, contentFields: [], attrFields: [], children: [] })
const blankChild = () => ({
  id: undefined,
  type: '',
  position: 0,
  contentFields: [],
  attrFields: [],
  children: []  // now can have children of children
})

const addSection    = () => form.value.sections.push(blankSection())
const removeSection = (si) => form.value.sections.splice(si, 1)
const addChild      = (si) => form.value.sections[si].children.push(blankChild())
const removeChild   = (si, ci) => form.value.sections[si].children.splice(ci, 1)

const addContentField         = (si)      => form.value.sections[si].contentFields.push({ key: '', value: '' })
const removeContentField      = (si, fi)  => form.value.sections[si].contentFields.splice(fi, 1)
const addAttrField            = (si)      => form.value.sections[si].attrFields.push({ key: 'class', value: '' })
const removeAttrField         = (si, ai)  => form.value.sections[si].attrFields.splice(ai, 1)
const addChildContentField    = (si, ci)  => form.value.sections[si].children[ci].contentFields.push({ key: '', value: '' })
const removeChildContentField = (si, ci, fi) => form.value.sections[si].children[ci].contentFields.splice(fi, 1)

const addChildAttrField = (si, ci) => form.value.sections[si].children[ci].attrFields.push({ key: 'class', value: '' })

const removeChildAttrField = (si, ci, ai) => form.value.sections[si].children[ci].attrFields.splice(ai, 1)

const addChildOfChild = (si, ci) => {
  form.value.sections[si].children[ci].children.push(blankChild())
}

const removeChildOfChild = (si, ci, cci) => {
  form.value.sections[si].children[ci].children.splice(cci, 1)
}

const addChildContentFieldRecursive = (si, ci, cci) => {
  form.value.sections[si].children[ci].children[cci].contentFields.push({ key: '', value: '' })
}

const removeChildContentFieldRecursive = (si, ci, cci, fi) => {
  form.value.sections[si].children[ci].children[cci].contentFields.splice(fi, 1)
}

const addChildAttrFieldRecursive = (si, ci, cci) => {
  form.value.sections[si].children[ci].children[cci].attrFields.push({ key: 'class', value: '' })
}

const removeChildAttrFieldRecursive = (si, ci, cci, ai) => {
  form.value.sections[si].children[ci].children[cci].attrFields.splice(ai, 1)
}

// ── Media ─────────────────────────────────────────────────────────────────────
const blankMedia  = () => ({ id: undefined, type: 'image', file_path: '' })
const addMedia    = () => form.value.media.push(blankMedia())
const removeMedia = (mi) => form.value.media.splice(mi, 1)

// ── Map page → form ───────────────────────────────────────────────────────────
const pageToForm = (page) => ({
  id:     page.id,
  title:  page.title,
  slug:   page.slug,
  status: page.status,
  sections: (page.sections ?? []).map(s => ({
    id:            s.id,
    type:          s.type ?? '',
    position:      s.position ?? 0,
    contentFields: objToFields(s.content),
    attrFields:    objToFields(s.attributes),
   children: (s.children ?? []).map(c => ({
  id: c.id,
  type: c.type ?? '',
  position: c.position ?? 0,
  contentFields: objToFields(c.content),
  attrFields: objToFields(c.attributes)
})),
  })),
  media: (page.media ?? []).map(m => ({ id: m.id, type: m.type, file_path: m.file_path })),
})

// ── Build payload ─────────────────────────────────────────────────────────────
const buildChildPayload = (child) => ({
  ...(child.id ? { id: child.id } : {}),
  type: child.type,
  position: child.position,
  content: fieldsToObj(child.contentFields),
  attributes: fieldsToObj(child.attrFields),
  children: child.children.map(buildChildPayload)  // recursion!
})

const buildPayload = () => ({
  title: form.value.title,
  slug: form.value.slug,
  status: form.value.status,
  sections: form.value.sections.map(s => ({
    ...(s.id ? { id: s.id } : {}),
    type: s.type,
    position: s.position,
    content: fieldsToObj(s.contentFields),
    attributes: fieldsToObj(s.attrFields),
    children: s.children.map(buildChildPayload)
  })),
  media: form.value.media.filter(m => m.file_path.trim()).map(m => ({
    ...(m.id ? { id: m.id } : {}),
    type: m.type,
    file_path: m.file_path.trim()
  }))
})

// ── CRUD ──────────────────────────────────────────────────────────────────────
const fetchPages = async () => {
  try {
    loading.value = true
    const res = await api.get('pages')
    pages.value = res.data?.data ?? res.data
  } catch { showAlert('Failed to load pages.', 'error') }
  finally { loading.value = false }
}

const openCreate = () => { form.value = blankForm(); errors.value = {}; modal.value = { show: true, mode: 'create' } }
const openEdit   = (page) => { form.value = pageToForm(page); errors.value = {}; modal.value = { show: true, mode: 'edit' } }
const closeModal = () => { modal.value.show = false }

const submitForm = async () => {
  if (!validate()) return
  saving.value = true
  try {
    const payload = buildPayload()
    if (modal.value.mode === 'create') {
      const res = await api.post('pages', payload)
      pages.value.unshift(res.data?.data ?? res.data)
      showAlert('Page created.')
    } else {
      const res = await api.put(`pages/${form.value.id}`, payload)
      const updated = res.data?.data ?? res.data
      const idx = pages.value.findIndex(p => p.id === form.value.id)
      if (idx !== -1) pages.value[idx] = updated
      showAlert('Page updated.')
    }
    closeModal()
  } catch (e) {
    showAlert(e?.response?.data?.message || 'Something went wrong.', 'error')
  } finally { saving.value = false }
}

const confirmDelete = (page) => { deleteTarget.value = page }

const deletePage = async () => {
  saving.value = true
  try {
    await api.delete(`pages/${deleteTarget.value.id}`)
    pages.value = pages.value.filter(p => p.id !== deleteTarget.value.id)
    if (expandedId.value === deleteTarget.value.id) expandedId.value = null
    showAlert('Page deleted.')
    deleteTarget.value = null
  } catch { showAlert('Failed to delete page.', 'error') }
  finally { saving.value = false }
}

const formToNode = (s) => ({
  type: s.type,
  attributes: fieldsToObj(s.attrFields),
  content: fieldsToObj(s.contentFields),
  children: s.children.map(c => ({
    type: c.type,
    attributes: fieldsToObj(c.attrFields),
    content: fieldsToObj(c.contentFields),
    children: []
  }))
})


const previewPage = ref(null)
const SectionNode = defineComponent({
  props: { node: Object },
  setup(props) {
    return () => {
      const n = props.node
      const children = (n.children || []).map(c => h(SectionNode, { key: c.id || Math.random(), node: c }))

      const content = n.content ? Object.values(n.content).filter(v => v != null && v !== '') : []

      // Always render if it has children OR attributes (class/style) even if content is empty
      if (!children.length && !content.length && !n.attributes) {
        return null
      }

      return h('div', {
        class: ['section-node', n.type, n.attributes?.class].filter(Boolean).join(' '),
        style: n.attributes?.style || ''
      }, [...content, ...children])
    }
  }
})

const openPreview = async (pageId) => {
  previewPage.value = { loading: true, sections: [], media: [] } // open modal immediately

  try {
    const res = await api.get(`pages/${pageId}`)
    previewPage.value = res.data
  } catch (e) {
    console.error('Preview failed', e)
    previewPage.value = null
  }
}


onMounted(fetchPages)
</script>

